package io.knowledgebrain.collaboration;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.collaboration.api.enabled",havingValue="true")
final class CourseSharingContextController {
 private final CourseEnrollmentStore store;private final StudyController gate;private final GroupSpaceClient authority;private final GroupStore groups;private final MeterRegistry metrics;
 CourseSharingContextController(CourseEnrollmentStore store,StudyController gate,GroupSpaceClient authority,GroupStore groups,MeterRegistry metrics){this.store=store;this.gate=gate;this.authority=authority;this.groups=groups;this.metrics=metrics;}
 @PostMapping("/api/groups/{groupId}/courses/{courseId}/progress-sharing-context") ResponseEntity<?> context(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r)throws IOException{gate.query(r,Set.of());var token=gate.token(r);var group=GroupInput.id(groupId);var course=GroupInput.id(courseId);var v=GroupInput.json(gate.jsonBody(r));if(!v.isObject()||v.size()!=1||!v.path("participantIds").isArray()||v.path("participantIds").size()>100)throw GroupInput.bad();var ids=new ArrayList<UUID>();for(var n:v.path("participantIds")){if(!n.isString())throw GroupInput.bad();ids.add(GroupInput.id(n.asString()));}if(new HashSet<>(ids).size()!=ids.size())throw GroupInput.bad();var a=authority.sharing(token,group,ids,gate.trace(r));var cfg=groups.active(List.of(group));if(cfg.size()!=1||!cfg.getFirst().spaceId().equals(a.spaceId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Group unavailable");var result=store.sharingContext(course,a);metrics.counter("brain.collaboration.course.sharing.context.reads").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(result);}
}
